import React,{StrictMode,useState} from 'react';import{createRoot}from'react-dom/client';import{LanguageProvider}from'../../src/lib/LanguageContext';import StudyPronunciation from'../../src/features/study/components/StudyPronunciation';
function App(){const [question,setQuestion]=useState(0),[front,setFront]=useState(true),[rate,setRate]=useState(.9),[shown,setShown]=useState(true);return <LanguageProvider initialLanguage="zh-TW"><button onClick={()=>setQuestion(n=>n+1)}>Next</button><button onClick={()=>setFront(v=>!v)}>Flip</button><button onClick={()=>setRate(1.2)}>Rate</button><button onClick={()=>setShown(false)}>Close</button>{shown&&<StudyPronunciation text={question?'world':'hello'} direction="en-zh" question={String(question)} frontVisible={front} automatic rate={rate}/>}</LanguageProvider>;}createRoot(document.getElementById('root')).render(<StrictMode><App/></StrictMode>);
